-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Fundamentos de UI / UX' and a.numero = 18
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 18 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 18', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 18 (20 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/FUNDAMENTOS-DE-UI-UX/ATIVIDADES/ATIVIDADE-PRATICA-AULA-18.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Descreva o que é a baixa fidelidade e o que ela prioriza.', 0.2, 'Baixa fidelidade é a representação em estrutura e fluxo, feita à mão ou com wireframes simples em tons de cinza, sem preocupação estética. Ela prioriza a organização das telas e a ordem das ações.', 'Nota cheia: cita estrutura e fluxo como prioridade e menciona o uso de rascunhos ou wireframes em tons de cinza sem preocupação estética. Metade: cita só a estrutura ou só o rascunho, sem o caráter sem acabamento. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 1, 2, 'Descreva a média fidelidade e o que ainda fica sem definição nela.', 0.4, 'Média fidelidade já tem alinhamento e proporções exatas feitos no software, mas ainda não tem a paleta de cores definitiva nem fotografias finais. O que fica sem definição são as cores e as imagens finais.', 'Nota cheia: menciona alinhamento e proporções exatos e diz que cores definitivas e fotografias finais ainda não estão definidas. Metade: menciona só o alinhamento ou só a falta de cores definitivas. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 1, 3, 'Descreva a alta fidelidade e explique por que ela corresponde ao mock-up final.', 0.4, 'Alta fidelidade é o mock-up final, com cores, tipografia, ícones, fotos e contrastes aplicados com precisão pixel a pixel. Ela corresponde ao mock-up final porque reúne todos esses acabamentos já definidos.', 'Nota cheia: descreve os acabamentos (cores, tipografia, ícones, fotos, contrastes) com precisão e liga a alta fidelidade ao mock-up final. Metade: descreve os acabamentos, mas não faz a ligação com o mock-up final, ou o contrário. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 2, 1, 'Diga o que é um mock-up digital, com as suas palavras.', 0.2, 'Mock-up digital é um modelo estático de alta fidelidade que mostra como a interface vai parecer quando for lançada. Serve para inspecionar hierarquia, harmonia de cores e legibilidade.', 'Nota cheia: diz com as próprias palavras que é um modelo visual estático de alta fidelidade que mostra a aparência final da interface. Metade: define o mock-up de forma vaga, sem o caráter estático ou sem a aparência final. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 2, 2, 'Explique por que o mock-up não possui código nem banco de dados funcionando.', 0.4, 'O mock-up não tem código nem banco de dados funcionando por trás, porque é um modelo visual. Ele apenas mostra a aparência, sem executar ações.', 'Nota cheia: afirma que não há programação nem banco de dados funcionando e explica que o mock-up é só visual. Metade: afirma a ausência de código, sem explicar o motivo. Zero: em branco, diz que o mock-up tem código ou banco de dados, ou fora do tema.'),
      (v_atividade, 2, 3, 'Explique o papel do mock-up como guia técnico para os desenvolvedores front-end.', 0.4, 'O mock-up é um guia técnico para os desenvolvedores front-end, porque orienta espaçamentos e estilos exatos (cores, fontes, medidas) que devem ser seguidos na implementação.', 'Nota cheia: diz que o mock-up orienta o desenvolvedor front-end sobre espaçamentos e estilos exatos. Metade: diz que ele ajuda o desenvolvedor, sem citar espaçamentos ou estilos. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 3, 1, 'Diga qual é a principal função do protótipo de papel.', 0.2, 'A principal função do protótipo de papel é testar fluxos e ações de forma rápida, com custo mínimo e ajustes imediatos, validando a ordem das ações com colegas.', 'Nota cheia: diz que o protótipo de papel serve para testar fluxos e a ordem das ações de forma rápida e barata. Metade: cita só a rapidez ou só o teste, sem o foco em fluxo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 3, 2, 'Diga qual é a principal função do mock-up digital.', 0.4, 'A principal função do mock-up digital é mostrar a aparência final da tela, com cores, fontes, medidas e acabamento, para inspeção visual e como guia para o desenvolvedor.', 'Nota cheia: diz que o mock-up digital mostra a aparência final (acabamento visual, cores, fontes ou medidas). Metade: diz só que é mais bonito ou mais detalhado, sem o objetivo visual. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 3, 3, 'Explique por que o mock-up digital não deve inventar passos que não foram testados no papel.', 0.4, 'O mock-up não deve inventar passos que não foram testados no papel, porque alterar o fluxo sem teste prévio quebra a validação feita no papel e pode introduzir novos erros de usabilidade.', 'Nota cheia: explica que criar passos não testados quebra a validação do papel e pode trazer erros de usabilidade. Metade: diz que não se deve inventar passos, sem explicar o efeito na validação. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 4, 1, 'Descreva o que é um frame no editor gráfico.', 0.2, 'O frame é a prancheta do editor gráfico, o espaço de tela com as dimensões exatas do dispositivo escolhido. É nele que a tela é montada.', 'Nota cheia: diz que o frame é o espaço/prancheta da tela com as dimensões do dispositivo. Metade: diz que é uma área de desenho, sem citar as dimensões do dispositivo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 4, 2, 'Explique por que a dimensão de 375 × 812 px é usada como exemplo de celular.', 0.4, '375 × 812 px é usado como exemplo de celular porque corresponde às dimensões de uma tela de celular, e é a medida indicada na aula para o frame de dispositivo móvel.', 'Nota cheia: relaciona 375 × 812 px às dimensões de tela de celular, como exemplo indicado na aula. Metade: diz que é uma medida de celular, sem explicar a relação com o dispositivo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 4, 3, 'Explique o que acontece com a leitura da tela se o frame for criado sem a dimensão do dispositivo.', 0.4, 'Se o frame for criado sem a dimensão do dispositivo, a leitura da tela muda: os elementos ficam em proporção errada, podem não caber ou sair da área visível, e o mock-up deixa de representar a tela real.', 'Nota cheia: explica que sem a dimensão certa a proporção e o encaixe dos elementos ficam errados e o mock-up não representa a tela real. Metade: diz só que a tela fica errada, sem explicar o efeito. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 5, 1, 'Diga o que é a regra da grade de 8 pixels.', 0.2, 'A regra da grade de 8 pixels organiza os espaçamentos e as medidas usando múltiplos de 8, para que nada fique solto "no olho".', 'Nota cheia: diz que a regra usa múltiplos de 8 px para organizar espaçamentos e medidas. Metade: diz só que é uma grade ou um padrão de medidas, sem o múltiplo de 8. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 5, 2, 'Dê exemplos de medidas que usam múltiplos de 8, como espaçamentos entre cards e alturas de botões.', 0.4, 'Exemplos: espaçamentos entre cards, margens e alturas de botões usando 8, 16, 24 ou 32 px.', 'Nota cheia: dá pelo menos dois exemplos válidos (espaçamento entre cards, margens ou alturas de botões) com valores múltiplos de 8. Metade: dá apenas um exemplo válido ou só valores genéricos. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 5, 3, 'Explique como a repetição desse ritmo gera equilíbrio e conforto visual ao usuário.', 0.4, 'A repetição do mesmo ritmo de espaçamento cria harmonia e equilíbrio, de modo que o usuário sente conforto visual sem perceber o motivo.', 'Nota cheia: liga a repetição do ritmo ao equilíbrio e ao conforto visual do usuário. Metade: diz que o ritmo deixa a tela mais organizada, sem ligar ao conforto do usuário. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 6, 1, 'Diga qual é a margem lateral usual indicada na aula.', 0.2, 'A margem lateral usual indicada na aula é de 16 px (ou 24 px, conforme o caso), medida a partir do limite da tela.', 'Nota cheia: cita 16 px ou 24 px como margem lateral usual. Metade: cita uma margem sem valor, ou um valor fora do indicado pela aula com justificativa coerente. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 6, 2, 'Explique por que as margens laterais devem ser consistentes em todas as telas.', 0.4, 'As margens devem ser consistentes em todas as telas para que o conteúdo tenha o mesmo alinhamento nas bordas, dando unidade ao aplicativo e evitando elementos encostados na borda do celular.', 'Nota cheia: diz que a consistência mantém o alinhamento e a unidade entre telas e evita elementos colados na borda. Metade: diz só que a margem deve ser igual, sem o efeito no alinhamento. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 6, 3, 'Explique como a margem orienta a largura de um botão que ocupa a área útil da tela.', 0.4, 'A margem define a área útil da tela. Um botão que ocupa a área útil tem a largura da tela menos as margens esquerda e direita, sem encostar nas bordas.', 'Nota cheia: explica que a margem delimita a área útil e que o botão ocupa essa área, descontando as margens. Metade: diz que a margem influencia o botão, sem explicar o cálculo da área útil. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 7, 1, 'Diga qual é a área útil da tela, descontando as margens.', 0.2, 'A área útil é 375 − 16 − 16 = 343 px, ou seja, a largura da tela descontadas as duas margens laterais de 16 px.', 'Nota cheia: chega a 343 px e mostra que descontou as duas margens. Metade: desconta só uma margem, ou chega a valor próximo com erro de conta, mas mostra o raciocínio. Zero: em branco, valor errado sem raciocínio ou fora do tema.'),
      (v_atividade, 7, 2, 'Mostre a conta que leva à largura do botão.', 0.4, '375 − 16 − 16 = 343 px. A largura do botão é 343 px.', 'Nota cheia: mostra a conta 375 − 16 − 16 = 343 px. Metade: mostra a conta com erro de cálculo, mas com a lógica correta de subtrair as margens. Zero: em branco, sem conta, ou fora do tema.'),
      (v_atividade, 7, 3, 'Explique por que o cálculo deve ser feito antes de aplicar o botão no mock-up, e não por estimativa visual.', 0.4, 'O cálculo deve ser feito antes para que o botão tenha a largura exata e fique alinhado à margem da grade, em vez de depender da estimativa visual, que pode deixá-lo desalinhado.', 'Nota cheia: explica que o cálculo garante precisão e alinhamento à grade, e que a estimativa visual pode errar. Metade: diz que o cálculo é melhor, sem explicar o motivo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 8, 1, 'Descreva o nível do título da tela e o tamanho indicado para ele.', 0.2, 'O título da tela deve ter entre 24 e 28 px e informar o objetivo imediato, como "Escolha a Data".', 'Nota cheia: indica o tamanho de 24 a 28 px para o título e exemplo de objetivo imediato. Metade: indica o tamanho sem o exemplo, ou o exemplo sem o tamanho. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 8, 2, 'Descreva os subtítulos e rótulos, com o tamanho indicado e um exemplo de uso.', 0.4, 'Subtítulos e rótulos devem ter entre 16 e 18 px e servem para nomear campos, especialidades ou botões. Exemplo: o rótulo "Especialidade" ou o nome de um profissional.', 'Nota cheia: indica 16 a 18 px e dá um exemplo de uso (campo, especialidade ou botão). Metade: indica o tamanho sem exemplo, ou o exemplo sem o tamanho. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 8, 3, 'Explique qual é a função do texto de apoio e por que ele deve ser menor que os outros níveis.', 0.4, 'O texto de apoio (12 a 14 px) traz instruções secundárias e mensagens de ajuda. Deve ser menor para não competir com o título e os rótulos, mantendo a hierarquia visual.', 'Nota cheia: indica a função de instrução secundária e explica que o tamanho menor preserva a hierarquia. Metade: diz a função ou o tamanho, sem a razão hierárquica. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 9, 1, 'Diga o que é uma camada no editor gráfico.', 0.2, 'Camada é um nível individual de sobreposição gráfica onde cada elemento fica e pode ser editado. As camadas são empilhadas, e o painel de camadas lista os objetos.', 'Nota cheia: diz que a camada é um nível individual de sobreposição, onde cada objeto fica e pode ser editado. Metade: diz só que é um nível ou uma parte do desenho, sem a ideia de empilhamento. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 9, 2, 'Explique por que o fundo deve ficar na base da lista de camadas e o conteúdo, no topo.', 0.4, 'O fundo fica na base porque deve ficar atrás de tudo. O conteúdo fica no topo para que textos e ícones permaneçam visíveis acima dos cards.', 'Nota cheia: explica que o fundo fica atrás para não cobrir o conteúdo, e o conteúdo no topo para ficar visível. Metade: diz só uma das duas partes. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 9, 3, 'Explique a causa provável do texto sumido e como verificá-la no painel de camadas.', 0.4, 'A causa provável é o texto ter ficado atrás do retângulo do card, na ordem de empilhamento. Para verificar, deve-se conferir no painel de camadas se o texto está abaixo do retângulo e subi-lo para o topo.', 'Nota cheia: aponta a camada do texto abaixo do retângulo do card como causa e indica verificar no painel de camadas. Metade: aponta a causa, sem a forma de verificar, ou o contrário. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 10, 1, 'Descreva o problema causado por nomes padrão como "Retângulo 54".', 0.2, 'Nomes padrão como "Retângulo 54" não dizem o que o objeto é nem para que serve, o que confunde a edição e a localização de elementos na lista de camadas.', 'Nota cheia: diz que o nome padrão não informa a função do objeto e atrapalha a edição. Metade: diz só que é confuso, sem o motivo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 10, 2, 'Explique como nomes claros ajudam quem for editar o mock-up depois.', 0.4, 'Nomes claros permitem encontrar e editar cada elemento rapidamente, inclusive para outra pessoa que receber o arquivo depois.', 'Nota cheia: diz que nomes claros facilitam achar e editar os elementos, inclusive para outras pessoas. Metade: diz só que facilita a edição, sem citar a outra pessoa. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 10, 3, 'Dê um exemplo de nome de camada descritivo para o botão de avanço da tela.', 0.4, 'Exemplo: "Botão de avanço" ou "Botao_Avancar", um nome que descreve o elemento e sua função.', 'Nota cheia: dá um nome descritivo que indica o elemento e sua função. Metade: dá um nome vago, como "Botão 2", ou genérico. Zero: em branco, nome padrão ou fora do tema.'),
      (v_atividade, 11, 1, 'Diga o que é um componente, com as suas palavras.', 0.2, 'Componente é um bloco mestre reutilizável de interface. Em vez de redesenhar o mesmo elemento, cria-se um componente mestre que gera instâncias dele.', 'Nota cheia: diz que o componente é um bloco reutilizável e que o mestre gera as instâncias. Metade: diz só que é um elemento reutilizável, sem o mestre e as instâncias. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 11, 2, 'Explique o que acontece com as instâncias quando o componente mestre é alterado.', 0.4, 'Quando o componente mestre é alterado, todas as instâncias são atualizadas automaticamente. No caso do botão, o novo raio da borda vale em todas as telas.', 'Nota cheia: diz que as instâncias são atualizadas automaticamente quando o mestre muda. Metade: diz que as instâncias mudam, sem falar em atualização automática. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 11, 3, 'Explique como essa solução evita trabalho repetitivo e mantém a mesma linguagem visual.', 0.4, 'A solução evita redesenhar o botão em cada tela, economiza tempo e garante que todo o aplicativo tenha a mesma linguagem visual, pelo princípio de repetição.', 'Nota cheia: cita a economia de trabalho repetitivo e a consistência visual do sistema. Metade: cita só a economia de tempo ou só a consistência. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 12, 1, 'Descreva a prancheta central (canvas).', 0.2, 'A prancheta central (canvas) é o espaço onde o desenho é feito, com as telas e os elementos da interface.', 'Nota cheia: diz que a prancheta é o espaço central de desenho onde a tela é montada. Metade: diz só que é a área de trabalho, sem a função. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 12, 2, 'Descreva a barra de criação e as ferramentas que ela reúne.', 0.4, 'A barra de criação reúne as ferramentas de formas (retângulo, elipse, linha), caixa de texto e caneta, usadas para construir botões e cards.', 'Nota cheia: diz que a barra reúne as ferramentas de criação (formas, texto, caneta ou vetores) e que servem para construir botões e cards. Metade: cita só algumas ferramentas, sem a função. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 12, 3, 'Descreva os painéis de camadas e de estilos e o que se configura em cada um.', 0.4, 'O painel de camadas mostra a árvore hierárquica de todos os objetos, organizados de baixo para cima. O painel de estilos configura preenchimento, contorno, raio de borda, opacidade, fonte e alinhamento.', 'Nota cheia: descreve o camada como lista hierárquica dos objetos e o estilo como configurações de cor, borda, fonte ou alinhamento. Metade: descreve só um dos painéis. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 13, 1, 'Explique como um retângulo do papel vira um botão ou um card no digital.', 0.2, 'Um retângulo do papel vira um botão ou um card no digital, com a forma geométrica traduzida para um elemento de interface, mantendo a posição e a função testadas.', 'Nota cheia: diz que o retângulo vira botão ou card no digital, mantendo a função testada. Metade: diz que vira um elemento de interface, sem citar botão ou card. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 13, 2, 'Explique a regra de contraste entre fundo e texto no passo para o digital.', 0.4, 'Fundo e texto devem respeitar a proporção mínima de legibilidade indicada pela aula (WCAG), para que o texto seja legível no digital.', 'Nota cheia: cita a regra de contraste entre fundo e texto e a proporção mínima de legibilidade (WCAG). Metade: diz que o contraste deve ser bom, sem citar a proporção mínima. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 13, 3, 'Explique como a disposição das informações segue o padrão Z ou F na tela digital.', 0.4, 'As informações cruciais devem seguir o padrão Z ou F, que é o caminho natural de leitura da tela, colocando os elementos mais importantes nos pontos de maior atenção.', 'Nota cheia: diz que a disposição segue o padrão Z ou F e que as informações importantes ficam nesse caminho. Metade: cita o padrão sem explicar a disposição das informações. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 14, 1, 'Diga o que a aula indica como referência para a proporção mínima de legibilidade.', 0.2, 'A aula indica como referência a proporção mínima de legibilidade do WCAG entre fundo e texto.', 'Nota cheia: cita o WCAG e a proporção mínima de contraste para legibilidade. Metade: cita contraste ou legibilidade, sem o WCAG. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 14, 2, 'Explique por que o digital melhora a legibilidade e o contraste em relação ao papel.', 0.4, 'O digital permite conferir a cor exata com precisão pixel a pixel e ajustar o contraste antes de a tela ir para a equipe. No papel, a cor não é definida e não há como medir.', 'Nota cheia: diz que o digital permite definir cores exatas e medir ou ajustar o contraste com precisão. Metade: diz só que é mais preciso, sem ligar ao contraste. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 14, 3, 'Explique o que a equipe deve fazer se o texto cinza não atingir a proporção mínima.', 0.4, 'A equipe deve ajustar a cor do texto ou do fundo (por exemplo, escurecer o texto cinza) até atingir a proporção mínima, e só então seguir a tela para a equipe.', 'Nota cheia: propõe ajustar as cores do texto ou do fundo e conferir a proporção mínima antes de seguir. Metade: propõe ajustar, sem conferir a proporção. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 15, 1, 'Descreva o que acontece com a consistência quando cada card é desenhado de um jeito.', 0.2, 'Quando cada card é desenhado de um jeito, a interface fica sem padrão: cada card tem medidas, cores ou formas diferentes, e o usuário sente a tela desorganizada.', 'Nota cheia: diz que cards desenhados de forma diferente quebram o padrão e a consistência visual. Metade: diz só que fica diferente, sem falar em padrão ou consistência. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 15, 2, 'Explique a relação entre o princípio de repetição e o uso de componentes.', 0.4, 'O princípio de repetição garante unidade: elementos iguais repetidos mantêm a coerência, e o componente é a forma prática de repetir o mesmo elemento com o mesmo visual.', 'Nota cheia: liga a repetição à unidade visual e diz que o componente é a forma de reutilizar o mesmo elemento. Metade: cita a repetição ou o componente, sem a ligação. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 15, 3, 'Explique por que os componentes devem ser reutilizados nas duas telas do agendamento.', 0.4, 'Os componentes devem ser reutilizados nas duas telas para que o agendamento tenha a mesma linguagem visual do início ao fim, e o usuário não se sinta em outro aplicativo.', 'Nota cheia: diz que reutilizar nas duas telas mantém a consistência do fluxo de agendamento. Metade: diz que deve ser reutilizado, sem ligar ao fluxo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 16, 1, 'Explique o que é a fidelidade estrutural em relação ao papel testado.', 0.2, 'Fidelidade estrutural é manter, no digital, a ordem dos passos e a posição dos elementos validados no papel, sem mudar a lógica testada com os colegas.', 'Nota cheia: diz que é manter a ordem dos passos e a posição dos elementos testados no papel. Metade: diz só que é seguir o papel, sem a ordem ou a posição. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 16, 2, 'Diga qual decisão deve ser tomada sobre a posição do botão e por quê.', 0.4, 'A decisão é manter o botão de avanço no canto inferior, onde ficou no papel, porque a mudança para o topo altera uma posição que não foi testada e pode quebrar a validação.', 'Nota cheia: decide manter o botão no canto inferior e justifica pela fidelidade ao papel testado. Metade: decide manter, sem justificar, ou justifica sem a decisão clara. Zero: em branco, decide mudar, ou fora do tema.'),
      (v_atividade, 16, 3, 'Explique o que o digital pode melhorar sem alterar a ordem das ações testadas.', 0.4, 'O digital pode melhorar o acabamento, as cores, a tipografia, o contraste e os ícones, sem alterar a ordem das ações nem a posição testada dos elementos principais.', 'Nota cheia: cita melhorias visuais (cores, tipografia, contraste, ícones) e diz que a ordem das ações não muda. Metade: cita melhorias visuais, sem a ressalva sobre a ordem. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 17, 1, 'Explique o que é o registro de decisões e dê um exemplo com a cor escolhida.', 0.2, 'O registro de decisões explica por que cada escolha foi feita. Exemplo: a cor azul ciano foi escolhida para transmitir calma e profissionalismo na área de saúde.', 'Nota cheia: explica que o registro justifica as escolhas e dá o exemplo da cor com a razão (calma e profissionalismo na saúde). Metade: explica o registro, sem exemplo, ou dá o exemplo sem a razão. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 17, 2, 'Explique o que é o registro de alterações em relação ao protótipo de papel.', 0.4, 'O registro de alterações mostra quais problemas observados no protótipo de papel foram corrigidos no digital.', 'Nota cheia: diz que o registro lista os problemas do papel que foram corrigidos no digital. Metade: diz que registra mudanças, sem ligar ao papel. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 17, 3, 'Explique o que deve constar na ficha técnica do mock-up.', 0.4, 'A ficha técnica traz os tamanhos de fontes, os códigos de cores hexadecimais e os espaçamentos anotados do mock-up.', 'Nota cheia: cita pelo menos dois itens (fontes, cores hexadecimais, espaçamentos). Metade: cita um item. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 18, 1, 'Diga quais informações cada etapa do registro deve trazer.', 0.2, 'Cada etapa do registro deve trazer a tela trabalhada, o que mudou em relação ao protótipo de papel e por que a mudança foi feita.', 'Nota cheia: cita os três elementos (tela, mudança em relação ao papel, motivo). Metade: cita dois dos três. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 18, 2, 'Escreva uma frase de registro para a tela de seleção, relacionando a ordem dos elementos ao papel testado.', 0.4, 'Exemplo: "Tela de seleção: mantive a ordem dos elementos testada no papel; ajustei o alinhamento do botão na grade para deixar a composição consistente."', 'Nota cheia: frase de registro que cita a tela de seleção, relaciona a ordem dos elementos ao papel testado e explica a mudança. Metade: frase que cita a tela ou o papel, sem a relação completa. Zero: em branco, frase genérica ou fora do tema.'),
      (v_atividade, 18, 3, 'Explique quais pontos da tela ainda merecem conferência, como alinhamento, legibilidade ou camadas.', 0.4, 'Devem ser conferidos o alinhamento do botão e dos cards na grade, a legibilidade dos textos (contraste e tamanhos) e a organização das camadas, para que não haja texto escondido.', 'Nota cheia: cita pelo menos dois pontos (alinhamento, legibilidade, camadas) com a razão de conferi-los. Metade: cita um ponto. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 19, 1, 'Diga por que nem tudo que aparece na busca da internet pode ser usado.', 0.2, 'Nem tudo que aparece na busca da internet pode ser usado, porque imagens e ícones têm autores e proteções legais.', 'Nota cheia: diz que recursos da internet têm autor e proteção legal, por isso nem tudo pode ser usado. Metade: diz só que pode ter direito autoral, sem a razão. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 19, 2, 'Explique o risco de infração para um projeto comercial.', 0.4, 'Usar recursos protegidos sem autorização gera risco de infração e pode invalidar um projeto comercial, com consequências legais e financeiras.', 'Nota cheia: diz que há risco de infração e que pode invalidar o projeto comercial. Metade: diz só que há risco legal, sem ligar ao projeto comercial. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 19, 3, 'Descreva a conduta correta ao escolher ícones e fotos para o mock-up.', 0.4, 'A conduta correta é usar recursos com licença conhecida e autorizada (por exemplo, Creative Commons) e registrar a origem e a licença de cada ícone e foto, ou criar os próprios recursos.', 'Nota cheia: cita o uso de recursos com licença autorizada e a verificação da origem ou licença. Metade: cita só a licença, sem a verificação, ou só criar recursos próprios. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 20, 1, 'Descreva as três fases do processo de criação, na ordem em que acontecem.', 0.2, 'As três fases, na ordem, são: 1) Planejamento (pesquisa, storyboard e protótipo de papel testado); 2) Transposição (frames, blocos com grade, cores e componentes mestre); 3) Acabamento (teste de contraste, documentação e preparação legal).', 'Nota cheia: cita as três fases na ordem correta, com pelo menos um conteúdo de cada. Metade: cita as três fases fora de ordem ou sem conteúdo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 20, 2, 'Cite os critérios de avaliação coletiva e explique o que cada um observa.', 0.4, 'Os critérios de avaliação coletiva são: Estrutura (alinhamento e proporção dos blocos), Legibilidade (contraste e fontes), Consistência (componentes e botões padronizados) e Acabamento (camadas e detalhes visuais).', 'Nota cheia: cita os quatro critérios e explica o que cada um observa. Metade: cita dois ou três critérios com explicação, ou os quatro sem explicação. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 20, 3, 'Explique como um feedback construtivo, com soluções técnicas e sem críticas pessoais, aplica a amabilidade no trabalho em equipe.', 0.4, 'O feedback construtivo aponta soluções técnicas, como alinhar o botão à grade ou aumentar o contraste, e não faz críticas pessoais. Assim pratica a amabilidade no trabalho em equipe.', 'Nota cheia: diz que o feedback aponta soluções técnicas e evita críticas pessoais, ligando isso à amabilidade. Metade: diz que o feedback deve ser gentil, sem o foco em solução técnica. Zero: em branco, errado ou fora do tema.');
end $$;
